#!/usr/bin/env bash
# Write backend/<svc>/.gitignore listing every top-level name pip installed into the service dir.
# pip records its files in *.dist-info/RECORD; deriving the list from those means a dependency that
# installs as a single top-level module (typing_extensions.py) is ignored automatically instead of
# being tracked by the *.py allow-list and counted by coverage (AGENTS.md -> AD-02).
# The generated file is itself ignored by the root rule /backend/[!_]*/*, so it is never committed.
# Usage: ./bin/pip-ignore.sh backend/<service>   (called by start-dev.sh after pip install)

set -euo pipefail

svc_dir="${1:?usage: $0 backend/<service>}"
out="$svc_dir/.gitignore"

shopt -s nullglob
records=("$svc_dir"/*.dist-info/RECORD)
shopt -u nullglob

{
    echo "# GENERATED by bin/pip-ignore.sh from pip's dist-info RECORD files. Do not edit or commit."
    echo "# Everything pip installed here for hot-reload; read by git and by the coverage plugin."
    if [ ${#records[@]} -gt 0 ]; then
        # first path component of each installed file; ../ entries point outside the dir
        cut -d, -f1 "${records[@]}" | cut -d/ -f1 | grep -v '^\.\.$' | sort -u | sed 's|^|/|'
    fi
} > "$out"

echo "  ✓ $(($(wc -l < "$out") - 2)) pip-installed names ignored in $(basename "$svc_dir")"
